    "name": "Apse Halo, Concentric Andamento",
    "glsl": "// knobs: A=tessera size B=grout width C=glint sharpness  (cursor = halo centre)\nfloat h1(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\nfloat h2(vec2 p){return fract(sin(dot(p,vec2(269.5,183.3)))*23421.6313);}\nfloat vn(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);\n    return mix(mix(h1(i),h1(i+vec2(1.0,0.0)),f.x),mix(h1(i+vec2(0.0,1.0)),h1(i+vec2(1.0,1.0)),f.x),f.y);}\nfloat fbm(vec2 p){float s=0.0,a=0.5;for(int i=0;i<4;i++){s+=a*vn(p);p=p*2.03+vec2(1.7,9.2);a*=0.55;}return s;}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord){\n    vec2 R=iResolution.xy;\n    vec2 uv=(fragCoord-0.5*R)/R.y;\n    float mA=step(1.0,length(iMouse.xy));\n    vec2 c=mix(vec2(0.0,0.03),(iMouse.xy-0.5*R)/R.y,mA);\n    float flick=0.85+0.15*sin(iTime*8.9+1.6*sin(iTime*20.7))+0.08*iAudio.x;\n\n    vec2 q=uv-c;\n    q+=0.004*vec2(sin(q.y*11.0+0.7),sin(q.x*9.0));\n    float r=length(q), ang=atan(q.y,q.x);\n\n    // andamento: rows are the isolines of r, tiles run along the course\n    float pv=0.013+0.026*iKnobA;\n    float ring=floor(r/pv);\n    float rc=(ring+0.5)*pv;\n    float nc=max(6.0,floor(6.2831*rc/(pv*1.06)));\n    float pa=6.2831/nc;\n    float ao=h1(vec2(ring,5.0))*pa;\n    float u=(ang+3.14159+ao)/pa;\n    vec2 cell=vec2(floor(u),ring);\n    float r1=h1(cell), r2=h2(cell), r3=h1(cell+7.7), r4=h2(cell+19.1);\n    vec2 l=vec2((fract(u)-0.5)*(rc*pa/pv), fract(r/pv)-0.5);\n    l-=(vec2(r3,r4)-0.5)*0.11;\n    float a=(r1-0.5)*0.20, ca=cos(a), sa=sin(a);\n    l=vec2(ca*l.x-sa*l.y, sa*l.x+ca*l.y);\n\n    float g=0.030+0.130*iKnobB;\n    vec2 he=(0.5-g)*(0.82+0.34*vec2(r2,r4));\n    vec2 dd=he-abs(l);\n    float m=smoothstep(0.0,1.5/(pv*R.y),min(dd.x,dd.y));\n\n    // apse bands: nimbus, ruby fillet, cobalt, bone halo rows, gold ground\n    vec3 gold=vec3(0.88,0.64,0.22), ruby=vec3(0.42,0.11,0.12);\n    vec3 cob=vec3(0.055,0.135,0.450), bone=vec3(0.76,0.74,0.66);\n    float s1=step(0.130,rc), s2=step(0.185,rc), s3=step(0.290,rc), s4=step(0.360,rc);\n    vec3 alb=mix(bone*1.10, mix(ruby, mix(cob, mix(bone,gold,s4), s3), s2), s1);\n    float bord=step(0.620,rc)*(1.0-step(0.700,rc));\n    alb=mix(alb,ruby*1.15,bord);\n    float ag=step(0.960,h2(cell+vec2(3.0,41.0)))*s4;\n    alb=mix(alb,vec3(0.60,0.63,0.66),ag);\n    alb*=0.74+0.52*r2;\n    alb=mix(alb,alb*vec3(0.84,1.02,0.97),r3*0.40);\n    alb*=0.92+0.12*vn(uv*430.0+cell);              // leaf pitting and mortar dust\n    float scr=sin((l.x*ca+l.y*sa)*80.0+r2*37.0);   // burnisher streaks in the gold\n    alb*=1.0+0.05*scr*s4;\n\n    // concave semi-dome: facet cone plus an inward bowl tilt\n    float tmax=mix(0.13,0.34,step(0.80,r3));\n    float th=tmax*sqrt(r4), ph=6.2831*r2;\n    vec3 dirv=vec3(q/max(r,1e-4),0.0);\n    vec3 n=normalize(vec3(sin(th)*cos(ph),sin(th)*sin(ph),cos(th))\n                     +vec3(l*0.28,0.0)-dirv*0.46*sin(min(r,1.0)*1.7));\n\n    vec2 lp=vec2(-0.14+0.40*sin(iTime*0.46),-0.42+0.18*cos(iTime*0.37));\n    vec3 V=vec3(0.0,0.0,1.0), P=vec3(uv,0.0);\n    vec3 L1=normalize(vec3(lp,0.55)-P);\n    vec3 L2=normalize(vec3(-lp.x*0.7,0.55,1.0)-P);\n    float k=mix(55.0,340.0,iKnobC)*(0.45+1.10*r1);\n    float sp=1.6*pow(max(dot(n,normalize(L1+V)),0.0),k)*flick\n            +0.5*pow(max(dot(n,normalize(L2+V)),0.0),k*0.6);\n    sp*=1.0+0.20*scr;\n    float dif=0.42+0.58*max(dot(n,L1),0.0)*flick+0.22*max(dot(n,L2),0.0);\n\n    vec3 col=alb*dif;\n    float edge=smoothstep(he.x*0.50,he.x,max(abs(l.x),abs(l.y)));\n    col=mix(col,col*vec3(0.45,0.94,0.86)+vec3(0.0,0.03,0.03),edge*0.65);\n    col+=vec3(1.0,0.94,0.78)*sp;\n    // gold-ground twinkle: each tessera catches the lamp on its own clock\n    float tw=pow(0.5+0.5*sin(iTime*(1.1+2.2*r1)+r2*39.0),9.0)*s4*(1.0-ag);\n    col+=vec3(1.0,0.90,0.62)*tw*0.30;\n    col+=vec3(1.0,0.86,0.55)*0.34*exp(-9.0*r*r)*flick;   // the nimbus itself glows\n\n    vec3 grout=vec3(0.145,0.125,0.104)*(0.62+0.72*h1(floor(uv*300.0)));\n    col=mix(grout,col,m);\n    col*=0.62+0.55*exp(-1.1*length(uv-vec2(lp.x,lp.y*0.4)))*flick;\n\n    // incense rises through the lamplight in two slow interleaved sheets\n    float haze=fbm(uv*2.3+vec2(0.15*sin(iTime*0.09),-iTime*0.05))\n              *fbm(uv*3.6+vec2(iTime*0.03,-iTime*0.09)+7.0);\n    col+=vec3(0.85,0.74,0.52)*haze*0.30*(0.35+0.65*exp(-2.4*r*r))*flick;\n\n    float lum=dot(col,vec3(0.30,0.59,0.11));\n    col*=mix(vec3(0.87,0.94,1.10),vec3(1.07,1.00,0.90),smoothstep(0.10,0.62,lum));\n    col+=vec3(0.028,0.021,0.014);\n    col=col/(1.0+0.30*col);\n    fragColor=vec4(pow(clamp(col,0.0,1.0),vec3(0.86)),1.0);\n}\n",
